<template>
  <section class="workspace-page control-page"><div class="workspace-heading"><div><p class="workspace-eyebrow">YOUR GOALS · YOUR CONTROL</p><h1>让计划，适合你的生活。</h1><p>目标、偏好、记忆与提醒，都由你决定。</p></div></div><div v-if="error" class="m-error" role="alert">{{ error }}<button class="m-btn m-btn--ghost m-btn--sm" @click="load">重新读取</button></div><p v-if="message" class="workspace-saved" role="status">{{ message }}</p><div v-if="loading" class="m-skeleton m-skeleton--block" />
    <template v-else-if="workspace">
      <nav class="workspace-segments" aria-label="个人工作区设置"><button v-for="item in tabs" :key="item.id" :aria-current="tab === item.id ? 'page' : undefined" @click="tab = item.id">{{ item.label }}</button></nav>
      <template v-if="tab === 'goals'">
        <form class="m-card workspace-form" @submit.prevent="saveGoal"><h2>{{ goalId ? '调整学习目标' : '先定一个小目标' }}</h2><div class="control-templates"><button v-for="example in ['课程期末复习', '技能入门', '英语练习', '论文阅读']" :key="example" type="button" @click="goalTitle = example">{{ example }}</button></div><label class="m-field"><span>这段时间，你想完成什么？</span><input v-model="goalTitle" class="m-input" maxlength="160" required placeholder="例如：两周内理解线性代数的核心概念" /></label><div class="control-pair"><label class="m-field"><span>目标日期（选填）</span><input v-model="deadline" class="m-input" type="date" /></label><label class="m-field"><span>每天可用时间</span><select v-model.number="dailyMinutes" class="m-input"><option v-for="n in [10,15,25,45,60,90,120]" :key="n" :value="n">{{ n }} 分钟</option></select></label></div><label v-if="goalId" class="m-field"><span>目标状态</span><select v-model="goalStatus" class="m-input"><option value="active">进行中</option><option value="paused">暂停</option><option value="completed">已完成</option><option value="archived">归档</option></select></label><div class="workspace-actions"><button class="m-btn m-btn--primary" :disabled="busy">保存目标</button><button v-if="goalId" class="m-btn m-btn--ghost" type="button" @click="resetGoal">新建另一个目标</button></div><p class="workspace-caption">预计时间是你的计划预算。完成目标状态由你确认，不作为测验成绩。</p></form>
        <div class="workspace-section-head"><h2>我的目标</h2><span>{{ workspace.goals.length }} 个</span></div><button v-for="goal in workspace.goals" :key="goal.id" class="m-card control-goal" @click="editGoal(goal)"><span class="workspace-row"><b>{{ goal.title }}</b><MobileIcon name="chevronRight" :size="16" /></span><small>{{ statusLabels[goal.status] }} · {{ goal.dailyMinutes }} 分钟 / 天 · {{ dateLabel(goal.deadline) }}</small></button><RouterLink to="/agent" class="workspace-context-link"><MobileIcon name="sparkle" :size="18" />让星枢把目标拆成任务 <MobileIcon name="chevronRight" :size="14" /></RouterLink>
      </template>
      <template v-else-if="tab === 'memory'">
        <div class="m-card workspace-form"><h2>个性化记忆</h2><label class="workspace-checkbox"><input v-model="preferences.memoryEnabled" type="checkbox" @change="savePreferences" /><span>允许使用我保存的偏好<small>关闭后不再使用这些记忆生成任务。你明确选择的目标和资料仍用于该次任务。</small></span></label><p class="workspace-caption">只保存你明确填写的目标与偏好，不主动推断健康、人格或其他无关敏感信息。</p></div><form v-if="preferences.memoryEnabled" class="m-card workspace-form" @submit.prevent="saveMemory"><label class="m-field"><span>{{ memoryId ? '修改这条记忆' : '希望星枢记住什么？' }}</span><textarea v-model="memoryContent" class="m-textarea" rows="3" maxlength="600" required placeholder="例如：先给一个例子，再解释概念。" /></label><button class="m-btn m-btn--ghost" :disabled="busy">保存记忆</button></form>
        <article v-for="memory in workspace.memories" :key="memory.id" class="m-card control-memory"><p>{{ memory.content }}</p><small>{{ memory.source }} · {{ dateLabel(memory.updatedAt) }}</small><div class="workspace-actions"><button class="workspace-text-action" :disabled="!preferences.memoryEnabled" @click="memoryId = memory.id; memoryContent = memory.content">编辑</button><button class="workspace-text-action" @click="memoryDeleteId = memory.id">删除</button></div><div v-if="memoryDeleteId === memory.id" class="workspace-confirm"><p>删除这条偏好记忆？已创建的学习目标会保留。</p><button class="m-btn m-btn--danger m-btn--sm" @click="deleteMemory(memory.id)">确认删除记忆</button><button class="workspace-text-action" @click="memoryDeleteId = ''">取消</button></div></article><p v-if="!workspace.memories.length" class="workspace-caption">还没有保存的记忆。你可以关闭记忆，照常学习。</p>
      </template>
      <template v-else-if="tab === 'reminders'">
        <form class="m-card workspace-form" @submit.prevent="savePreferences"><h2>温和提醒，按你的节奏</h2><label class="workspace-checkbox"><input v-model="preferences.reminderEnabled" type="checkbox" /><span>开启站内复习提醒<small>仅在 App 内显示到期事项，每天最多显示一组；关闭后不再展示。</small></span></label><label class="m-field"><span>每日提醒开始时间</span><input v-model="preferences.reminderTime" type="time" class="m-input" required /></label><div class="control-pair"><label class="m-field"><span>安静时段开始</span><input v-model="preferences.quietStart" class="m-input" type="time" required /></label><label class="m-field"><span>安静时段结束</span><input v-model="preferences.quietEnd" class="m-input" type="time" required /></label></div><button class="m-btn m-btn--primary" :disabled="busy">保存提醒偏好</button><p class="workspace-caption">当前版本没有接入系统推送，不会在后台向手机发送通知。复习间隔由你安排，不自动堆积任务。</p></form>
      </template>
      <template v-else>
        <div class="m-card workspace-form"><h2>数据与模型说明</h2><p>你的资料默认属于当前账号。资料问答先返回原文摘录；只有明确选择资料并确认星枢任务时，才会发送所选文字、目标及已开启的偏好给配置的模型服务。</p><p>模型不可用时会标记规则整理。上传资料和任务内容不会成为应用指令，也不会授权外部日历、分享或支付。</p><button class="m-btn m-btn--ghost" :disabled="busy" @click="exportData">导出我的学习工作区</button><p class="workspace-caption">导出包含目标、资料文字、笔记、任务产物、记忆、偏好与累计练习统计；不含密码或访问令牌。</p><RouterLink to="/library" class="workspace-text-action">管理或删除单份资料 →</RouterLink></div>
        <form class="m-card workspace-form" @submit.prevent="sendFeedback"><h2>让我们知道哪里不对</h2><label class="m-field"><span>错误或建议</span><textarea v-model="feedback" class="m-textarea" rows="3" maxlength="2000" required placeholder="可说明题目有误、引用不准确或界面问题，请勿填写密码。" /></label><button class="m-btn m-btn--primary" :disabled="busy">保存反馈记录</button><p class="workspace-caption">反馈保存到当前账号，状态可在下方查看。当前没有承诺自动人工处理时限。</p></form><div v-for="item in workspace.feedback" :key="item.id" class="m-card control-memory"><p>{{ item.content }}</p><small>已收到 · {{ item.id.slice(0,8) }}</small></div>
      </template>
    </template>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { apiGet } from '@/lib/api'
import MobileIcon from '@/mobile/components/MobileIcon.vue'
import { changeWorkspace, dateLabel, downloadText, loadWorkspace, type Goal, type Workspace } from '@/mobile/data/workspace'
const route = useRoute(), tabs = [{ id: 'goals', label: '目标' }, { id: 'memory', label: '记忆' }, { id: 'reminders', label: '提醒' }, { id: 'privacy', label: '数据与反馈' }], statusLabels: Record<string,string> = { active: '进行中', paused: '已暂停', completed: '已完成', archived: '已归档' }
const workspace = ref<Workspace | null>(null), loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), tab = ref('goals'), goalId = ref(''), goalTitle = ref(''), deadline = ref(''), dailyMinutes = ref(25), goalStatus = ref('active'), memoryId = ref(''), memoryContent = ref(''), memoryDeleteId = ref(''), feedback = ref('')
const preferences = reactive({ memoryEnabled: true, reminderEnabled: false, reminderTime: '18:00', quietStart: '22:00', quietEnd: '08:00' })
async function load() { error.value = ''; try { workspace.value = await loadWorkspace(); Object.assign(preferences, workspace.value.preferences) } catch (e) { error.value = e instanceof Error ? e.message : '读取失败' } finally { loading.value = false } }
onMounted(async () => { await load(); if (tabs.some(t => t.id === route.query.tab)) tab.value = String(route.query.tab) })
function resetGoal() { goalId.value = ''; goalTitle.value = ''; deadline.value = ''; goalStatus.value = 'active' }
function editGoal(goal: Goal) { goalId.value = goal.id; goalTitle.value = goal.title; deadline.value = goal.deadline || ''; dailyMinutes.value = goal.dailyMinutes; goalStatus.value = goal.status; document.querySelector<HTMLInputElement>('.control-page input')?.focus() }
async function action(path: string, body: unknown, success: string) { busy.value = true; error.value = ''; message.value = ''; try { await changeWorkspace(path, body); await load(); message.value = success; return true } catch (e) { error.value = e instanceof Error ? e.message : '保存失败'; return false } finally { busy.value = false } }
async function saveGoal() { if (await action('goals', { id: goalId.value || undefined, title: goalTitle.value, deadline: deadline.value || null, dailyMinutes: dailyMinutes.value, status: goalStatus.value }, '学习目标已保存。')) resetGoal() }
async function savePreferences() { await action('preferences', { ...preferences }, '偏好已保存。') }
async function saveMemory() { if (await action('memories', { id: memoryId.value || undefined, content: memoryContent.value }, '记忆已保存，可随时修改或关闭。')) { memoryId.value = ''; memoryContent.value = '' } }
async function deleteMemory(id: string) { await action('memories', { id, action: 'delete' }, '这条记忆已删除。'); memoryDeleteId.value = '' }
async function sendFeedback() { if (await action('feedback', { content: feedback.value }, '反馈记录已保存。')) feedback.value = '' }
async function exportData() { busy.value = true; try { const data = await apiGet('/api/workspace/export'); downloadText('智学星枢_学习工作区.json', JSON.stringify(data,null,2), 'application/json;charset=utf-8'); message.value = '已生成工作区导出文件。' } catch (e) { error.value = e instanceof Error ? e.message : '导出失败' } finally { busy.value = false } }
</script>
<style scoped>.control-templates { display: flex; flex-wrap: wrap; gap: 8px; }.control-templates button { min-height: 40px; border: 1px solid var(--m-border); border-radius: 12px; padding: 8px 12px; background: var(--m-primary-soft); color: var(--m-primary); font: inherit; font-size: 13px; }.control-pair { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }.control-pair input { min-width: 0; }.control-goal { display: grid; gap: 10px; width: 100%; text-align: left; color: var(--m-text); font: inherit; margin-bottom: 12px; cursor: pointer; }.control-goal b { font-size: 16px; line-height: 1.7; }.control-goal small,.control-memory small { font-size: 12px; color: var(--m-text-faint); }.control-memory { margin-top: 14px; }.control-memory p { margin: 0 0 10px; font-size: 15px; line-height: 1.8; }.control-page .workspace-form > p { font-size: 14px; line-height: 1.9; color: var(--m-text-dim); margin: 0; }</style>
